import { Client, GatewayIntentBits, EmbedBuilder, PermissionFlagsBits, ActivityType } from 'discord.js';
import fs from 'fs';
import path from 'path';

// Path Helper for isolated guild storage relative to workspace root
const DATA_DIR = path.join(process.cwd(), 'data', 'servers');

/**
 * Helper to ensure a guild directory and its JSON storage databases exist.
 */
function ensureGuildStorage(guildId) {
  const guildDir = path.join(DATA_DIR, guildId);
  if (!fs.existsSync(guildDir)) {
    fs.mkdirSync(guildDir, { recursive: true });
  }

  const files = {
    'settings.json': {
      enabled: true,
      welcome: {
        enabled: true,
        channelId: 'welcome-channel-id',
        mode: 'embed',
        title: 'Welcome to Nexor Studio!',
        description: 'We are thrilled to have you here, {user}! Make sure to check the rules and enjoy your stay in {server}.',
        color: '#5865F2',
        showServerIcon: true,
        showUserAvatar: true,
        bottomImage: 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=80',
        footerText: 'Server Member #{server.memberCount}',
        footerIcon: '',
        mentionUser: true
      },
      automod: {
        enabled: true,
        logChannelId: 'automod-logs',
        spamFilter: true,
        linkFilter: true,
        inviteFilter: true,
        mentionLimit: 5,
        capsFilter: false,
        badWords: ['scam', 'free-nitro', 'hack'],
        action: 'delete'
      },
      antiraid: {
        enabled: true,
        logChannelId: 'antiraid-logs',
        joinRateThreshold: 8,
        quarantineNewAccounts: true,
        accountAgeMinDays: 3,
        lockdownOnAttack: false,
        action: 'timeout'
      },
      antinuke: {
        enabled: true,
        logChannelId: 'antinuke-logs',
        channelCreateThreshold: 3,
        channelDeleteThreshold: 2,
        roleDeleteThreshold: 2,
        webhookThreshold: 1,
        action: 'remove_roles'
      },
      tickets: {
        enabled: true,
        panelTitle: 'Nexor Support Portal',
        panelDescription: 'Need assistance? Open a secure support ticket matching your inquiry category.',
        useDropdown: false,
        categories: [
          { id: 'cat-1', name: 'General Support', description: 'General server inquiries or role requests.', emoji: '💬', parentId: '123', supportRoles: ['Staff'], namingFormat: 'ticket-{user}', openingText: 'Thank you for reaching out. Support will be with you shortly.', requiredFields: ['Detailed Explanation'] },
          { id: 'cat-2', name: 'Billing & Payments', description: 'Donations, store purchases, or custom tier questions.', emoji: '💳', parentId: '124', supportRoles: ['Admin'], namingFormat: 'billing-{user}', openingText: 'Please provide proof of payment and invoice ID.', requiredFields: ['Order ID', 'Detailed Explanation'] },
          { id: 'cat-3', name: 'Report a Bug', description: 'Submit server or app issues directly to developers.', emoji: '🐛', parentId: '125', supportRoles: ['Developer'], namingFormat: 'bug-{user}', openingText: 'Please state the steps to reproduce the bug clearly.', requiredFields: ['Steps to Reproduce', 'Expected Result'] }
        ]
      }
    },
    'warnings.json': [],
    'backups.json': [],
    'invites.json': [
      { memberId: 'm-3342', memberTag: 'AlphaMark#0001', real: 42, fake: 3, rejoin: 8, left: 12, total: 29 },
      { memberId: 'm-9482', memberTag: 'Lumina#4412', real: 28, fake: 1, rejoin: 4, left: 6, total: 21 },
      { memberId: 'm-1024', memberTag: 'Tectonic#9988', real: 15, fake: 0, rejoin: 1, left: 2, total: 13 }
    ],
    'tickets_live.json': [],
    'audits.jsonl': ''
  };

  for (const [filename, defaultData] of Object.entries(files)) {
    const filePath = path.join(guildDir, filename);
    if (!fs.existsSync(filePath)) {
      if (filename.endsWith('.jsonl')) {
        fs.writeFileSync(filePath, defaultData);
      } else {
        fs.writeFileSync(filePath, JSON.stringify(defaultData, null, 2));
      }
    }
  }
}

/**
 * Load settings for a guild
 */
export function getGuildSettings(guildId) {
  ensureGuildStorage(guildId);
  const filePath = path.join(DATA_DIR, guildId, 'settings.json');
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    console.error(`Error reading settings for guild ${guildId}`, err);
    return {};
  }
}

/**
 * Save settings for a guild
 */
export function saveGuildSettings(guildId, data) {
  ensureGuildStorage(guildId);
  const filePath = path.join(DATA_DIR, guildId, 'settings.json');
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
}

/**
 * Add an audit log entry for a guild
 */
export function addGuildAudit(guildId, moduleName, action, reason, executorTag = 'SYSTEM') {
  ensureGuildStorage(guildId);
  const filePath = path.join(DATA_DIR, guildId, 'audits.jsonl');
  const auditId = 'evt-' + Math.random().toString(36).substring(2, 8);
  const caseIdNum = Math.floor(Math.random() * 5000) + 10000;
  
  const entry = {
    eventId: auditId,
    caseId: `NX-0${caseIdNum}`,
    guildId,
    module: moduleName,
    action,
    executorId: 'sys-node',
    executorTag,
    reason,
    status: 'success',
    createdAt: new Date().toLocaleTimeString('en-US', { hour12: false })
  };

  fs.appendFileSync(filePath, JSON.stringify(entry) + '\n');
}

/**
 * Get all audits for a guild
 */
export function getGuildAudits(guildId) {
  ensureGuildStorage(guildId);
  const filePath = path.join(DATA_DIR, guildId, 'audits.jsonl');
  try {
    const raw = fs.readFileSync(filePath, 'utf8').trim();
    if (!raw) return [];
    return raw.split('\n').map(line => JSON.parse(line)).reverse();
  } catch (err) {
    return [];
  }
}

// In-memory message tracker for Anti-Spam
const messageTimestamps = new Map();

// In-memory channel deletion counters for Anti-Nuke
const deletionTrackers = new Map();

/**
 * Create and initialize the Discord Client.
 */
export function initializeDiscordBot() {
  const token = process.env.DISCORD_BOT_TOKEN;
  if (!token) {
    console.log('[NexusBot SDK] DISCORD_BOT_TOKEN is missing. Bot module is running inside live Dashboard sandbox simulation.');
    return null;
  }

  const client = new Client({
    intents: [
      GatewayIntentBits.Guilds,
      GatewayIntentBits.GuildMembers,
      GatewayIntentBits.GuildMessages,
      GatewayIntentBits.MessageContent,
      GatewayIntentBits.GuildModeration,
      GatewayIntentBits.GuildInvites
    ]
  });

  client.once('ready', () => {
    console.log(`[NexusBot Gateway] Logged in as ${client.user.tag}`);
    client.user.setActivity('Shielding Guilds • v1.0.0', { type: ActivityType.Watching });
    
    // Register global interactions/slash commands on the bot client
    const commands = [
      {
        name: 'help',
        description: 'Displays NexusBot server security information.'
      },
      {
        name: 'warn',
        description: 'Issues a moderation warning to a member.',
        options: [
          { name: 'user', description: 'The user to warn', type: 6, required: true },
          { name: 'reason', description: 'Reason for warn ticket', type: 3, required: true }
        ]
      },
      {
        name: 'ban',
        description: 'Bans a malicious member from the server.',
        options: [
          { name: 'user', description: 'The user to ban', type: 6, required: true },
          { name: 'reason', description: 'Reason for ban', type: 3, required: true }
        ]
      },
      {
        name: 'lock',
        description: 'Initiates a lockdown of a channel or all channels.',
        options: [
          {
            name: 'target',
            description: 'Lock target selection',
            type: 3,
            required: true,
            choices: [{ name: 'all', value: 'all' }, { name: 'here', value: 'here' }]
          }
        ]
      },
      {
        name: 'backup',
        description: 'Backup commands.',
        options: [
          {
            name: 'action',
            description: 'Backup action',
            type: 3,
            required: true,
            choices: [{ name: 'create', value: 'create' }]
          }
        ]
      }
    ];

    client.application.commands.set(commands)
      .then(() => console.log('[NexusBot Gateway] Successfully registered Slash commands globally.'))
      .catch(err => console.error('[NexusBot Gateway] Command registration failed', err));
  });

  // Handle Slash Commands
  client.on('interactionCreate', async (interaction) => {
    if (!interaction.isChatInputCommand()) return;

    const { commandName, guildId, user } = interaction;
    if (!guildId) {
      return interaction.reply({ content: 'NexusBot commands can only be used inside Discord servers.', ephemeral: true });
    }

    ensureGuildStorage(guildId);
    const settings = getGuildSettings(guildId);

    // Help Command
    if (commandName === 'help') {
      const helpEmbed = new EmbedBuilder()
        .setTitle('🛰️ NexusBot Security Core')
        .setDescription('High-concurrency full-stack Discord security shield running on WispByte.')
        .setColor('#5865F2')
        .addFields(
          { name: '🛡️ AutoMod', value: 'Spam, link, and invite filters with rapid auto-warning actions.', inline: true },
          { name: '🚨 AntiRaid', value: 'Quarantining fresh accounts and dynamic join-rate attack detection.', inline: true },
          { name: '☢️ AntiNuke', value: 'Admin permission stripping and bulk channel deletion protection.', inline: true },
          { name: '📁 Commands', value: '`/help`, `/warn`, `/ban`, `/lock [all|here]`, `/backup create`' }
        )
        .setFooter({ text: 'Secure Isolation Mode' });

      return interaction.reply({ embeds: [helpEmbed] });
    }

    // Warn Command
    if (commandName === 'warn') {
      if (!interaction.member.permissions.has(PermissionFlagsBits.ModerateMembers)) {
        return interaction.reply({ content: '❌ Access Denied: You require `ModerateMembers` permission.', ephemeral: true });
      }

      const targetUser = interaction.options.getUser('user');
      const reason = interaction.options.getString('reason');

      const warningsPath = path.join(DATA_DIR, guildId, 'warnings.json');
      let warnings = [];
      try { warnings = JSON.parse(fs.readFileSync(warningsPath, 'utf8')); } catch (e) {}

      const warnId = `warn-${warnings.length + 1}`;
      const caseIdNum = warnings.length + 12395;
      const newWarn = {
        id: warnId,
        guildId,
        memberId: targetUser.id,
        memberTag: targetUser.tag,
        reason,
        source: 'manual',
        createdAt: new Date().toISOString().replace('T', ' ').substring(0, 16),
        executorId: user.id,
        executorTag: user.tag,
        caseId: `NX-0${caseIdNum}`,
        active: true
      };

      warnings.push(newWarn);
      fs.writeFileSync(warningsPath, JSON.stringify(warnings, null, 2));
      addGuildAudit(guildId, 'warnings', 'MEMBER_WARN', `Manually warned user ${targetUser.tag} for: ${reason}`, user.tag);

      const warnEmbed = new EmbedBuilder()
        .setTitle('⚠️ Member Warned')
        .setColor('#F59E0B')
        .addFields(
          { name: 'Target User', value: `${targetUser.tag} (<@${targetUser.id}>)`, inline: true },
          { name: 'Moderator', value: user.tag, inline: true },
          { name: 'Case ID', value: `NX-0${caseIdNum}`, inline: true },
          { name: 'Reason', value: reason }
        );

      return interaction.reply({ embeds: [warnEmbed] });
    }

    // Ban Command
    if (commandName === 'ban') {
      if (!interaction.member.permissions.has(PermissionFlagsBits.BanMembers)) {
        return interaction.reply({ content: '❌ Access Denied: You require `BanMembers` permission.', ephemeral: true });
      }

      const targetUser = interaction.options.getUser('user');
      const reason = interaction.options.getString('reason');

      try {
        await interaction.guild.members.ban(targetUser, { reason });
        addGuildAudit(guildId, 'moderation', 'MEMBER_BAN', `Banned user ${targetUser.tag} - Reason: ${reason}`, user.tag);

        const banEmbed = new EmbedBuilder()
          .setTitle('🔨 User Ban Success')
          .setColor('#EF4444')
          .addFields(
            { name: 'Target', value: targetUser.tag, inline: true },
            { name: 'Executor', value: user.tag, inline: true },
            { name: 'Reason', value: reason }
          );

        return interaction.reply({ embeds: [banEmbed] });
      } catch (err) {
        return interaction.reply({ content: `❌ Failed to ban user: ${err.message}`, ephemeral: true });
      }
    }

    // Lock Command
    if (commandName === 'lock') {
      if (!interaction.member.permissions.has(PermissionFlagsBits.ManageChannels)) {
        return interaction.reply({ content: '❌ Access Denied: You require `ManageChannels` permission.', ephemeral: true });
      }

      const target = interaction.options.getString('target');

      if (target === 'here') {
        try {
          await interaction.channel.permissionOverwrites.edit(interaction.guild.roles.everyone, {
            SendMessages: false
          });
          addGuildAudit(guildId, 'moderation', 'CHANNEL_LOCK', `Locked channel #${interaction.channel.name}`, user.tag);
          return interaction.reply({ content: `🔒 Channel <#${interaction.channel.id}> has been locked successfully.` });
        } catch (e) {
          return interaction.reply({ content: `❌ Lock failed: ${e.message}`, ephemeral: true });
        }
      } else if (target === 'all') {
        try {
          const channels = await interaction.guild.channels.fetch();
          let count = 0;
          for (const [_, ch] of channels) {
            if (ch.isTextBased()) {
              await ch.permissionOverwrites.edit(interaction.guild.roles.everyone, { SendMessages: false });
              count++;
            }
          }
          addGuildAudit(guildId, 'moderation', 'BULK_LOCK', `Bulk locked ${count} text channels`, user.tag);
          return interaction.reply({ content: `🚨 **Emergency Lockdown Activated**: Locked ${count} channels.` });
        } catch (e) {
          return interaction.reply({ content: `❌ Bulk lock failed: ${e.message}`, ephemeral: true });
        }
      }
    }

    // Backup Create
    if (commandName === 'backup' && interaction.options.getString('action') === 'create') {
      if (user.id !== interaction.guild.ownerId && !interaction.member.permissions.has(PermissionFlagsBits.Administrator)) {
        return interaction.reply({ content: '❌ Access Denied: Only server administrators can trigger structural backups.', ephemeral: true });
      }

      await interaction.deferReply({ ephemeral: true });

      try {
        const channels = await interaction.guild.channels.fetch();
        const roles = await interaction.guild.roles.fetch();

        const channelData = [...channels.values()].map(c => ({ name: c.name, type: c.type, parentName: c.parent?.name }));
        const roleData = [...roles.values()].map(r => ({ name: r.name, color: r.color, permissions: r.permissions.bitfield.toString() }));

        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
        let recoveryCode = 'NX-';
        for (let i = 0; i < 16; i++) {
          if (i > 0 && i % 4 === 0) recoveryCode += '-';
          recoveryCode += chars.charAt(Math.floor(Math.random() * chars.length));
        }

        const backupId = `bk-${Math.random().toString(36).substring(2, 8)}`;
        const backupsPath = path.join(DATA_DIR, guildId, 'backups.json');
        
        let backupsList = [];
        try { backupsList = JSON.parse(fs.readFileSync(backupsPath, 'utf8')); } catch (e) {}

        const newBk = {
          id: backupId,
          creatorName: user.tag,
          createdAt: new Date().toISOString().replace('T', ' ').substring(0, 16),
          channelCount: channelData.length,
          roleCount: roleData.length,
          size: `${Math.round(JSON.stringify({ channels: channelData, roles: roleData }).length / 1024)}KB`,
          channels: channelData,
          roles: roleData
        };

        backupsList.push(newBk);
        fs.writeFileSync(backupsPath, JSON.stringify(backupsList, null, 2));
        addGuildAudit(guildId, 'backups', 'BACKUP_CREATE', `Encrypted backup ${backupId} completed`, user.tag);

        // Try DMing the code to the user
        try {
          await user.send(`🔑 **NexusBot Cryptographic Backup Recovery Key** for server **${interaction.guild.name}**:\n\`\`\`\n${recoveryCode}\n\`\`\`\nKeep this code absolutely safe! It is required to restore structure.`);
        } catch (e) {
          return interaction.followUp({ content: `📁 Backup created! ID: **${backupId}**\n⚠️ *Warning: I could not DM you the recovery key. Please make sure your DMs are open.*` });
        }

        return interaction.followUp({ content: `📁 Backup created successfully! ID: **${backupId}**. Recovery key was sent to your direct messages.` });
      } catch (err) {
        return interaction.followUp({ content: `❌ Backup creation failed: ${err.message}` });
      }
    }
  });

  // Message Listener (AutoMod)
  client.on('messageCreate', async (message) => {
    if (!message.guildId || message.author.bot) return;

    const guildId = message.guildId;
    const settings = getGuildSettings(guildId);
    if (!settings?.automod?.enabled) return;

    const member = message.member;
    const content = message.content;

    // Permissions check - bypass mod team
    if (member?.permissions?.has(PermissionFlagsBits.ManageMessages)) return;

    let triggerAutoMod = false;
    let reason = '';

    // Spam Filter
    if (settings.automod.spamFilter) {
      const now = Date.now();
      const userKey = `${guildId}-${message.author.id}`;
      let timestamps = messageTimestamps.get(userKey) || [];
      timestamps.push(now);
      timestamps = timestamps.filter(t => now - t < 10000); // 10 seconds sliding window
      messageTimestamps.set(userKey, timestamps);

      if (timestamps.length > settings.automod.mentionLimit) {
        triggerAutoMod = true;
        reason = 'Rapid Chat Spamming (>5 msgs / 10s)';
      }
    }

    // Link Filter
    if (!triggerAutoMod && settings.automod.linkFilter) {
      const hasUrl = /(https?:\/\/[^\s]+)/g.test(content);
      if (hasUrl) {
        triggerAutoMod = true;
        reason = 'Unauthorized Link Sharing';
      }
    }

    // Invite Filter
    if (!triggerAutoMod && settings.automod.inviteFilter) {
      const hasInvite = /(discord\.gg|discord\.com\/invite)\/[^\s]+/g.test(content);
      if (hasInvite) {
        triggerAutoMod = true;
        reason = 'Unauthorized Server Invite Link';
      }
    }

    // Bad Words Filter
    if (!triggerAutoMod && settings.automod.badWords?.length > 0) {
      const lower = content.toLowerCase();
      const matched = settings.automod.badWords.find(word => lower.includes(word.toLowerCase()));
      if (matched) {
        triggerAutoMod = true;
        reason = `Banned keyword usage: "${matched}"`;
      }
    }

    if (triggerAutoMod) {
      try {
        await message.delete();
      } catch (e) {
        console.error('Failed to delete moderated message', e);
      }

      // Add warning automatically
      const warningsPath = path.join(DATA_DIR, guildId, 'warnings.json');
      let warnings = [];
      try { warnings = JSON.parse(fs.readFileSync(warningsPath, 'utf8')); } catch (e) {}

      const caseIdNum = warnings.length + 12395;
      const newWarn = {
        id: `warn-${warnings.length + 1}`,
        guildId,
        memberId: message.author.id,
        memberTag: message.author.tag,
        reason: `[AutoMod] ${reason}`,
        source: 'automod',
        createdAt: new Date().toISOString().replace('T', ' ').substring(0, 16),
        executorId: 'system-automod',
        executorTag: 'NexusBot AutoMod',
        caseId: `NX-0${caseIdNum}`,
        active: true
      };

      warnings.push(newWarn);
      fs.writeFileSync(warningsPath, JSON.stringify(warnings, null, 2));
      addGuildAudit(guildId, 'automod', 'MSG_DELETED', `Deleted message from ${message.author.tag} & warned user. Reason: ${reason}`, 'NexusBot AutoMod');

      // Alert in channel
      try {
        const warningAlert = await message.channel.send(`⚠️ <@${message.author.id}>, your message was removed under the server's **AutoMod policies** (${reason}).`);
        setTimeout(() => warningAlert.delete().catch(() => {}), 5000);
      } catch (e) {}
    }
  });

  // Guild Member Join (Welcome & AntiRaid)
  client.on('guildMemberAdd', async (member) => {
    const guildId = member.guild.id;
    ensureGuildStorage(guildId);
    const settings = getGuildSettings(guildId);

    // Welcome Trigger
    if (settings?.welcome?.enabled && settings.welcome.channelId) {
      const welcomeChannel = member.guild.channels.cache.get(settings.welcome.channelId);
      if (welcomeChannel) {
        let contentText = settings.welcome.description
          .replace(/{user}/g, `<@${member.id}>`)
          .replace(/{server}/g, `**${member.guild.name}**`);

        if (settings.welcome.mode === 'embed') {
          const embed = new EmbedBuilder()
            .setTitle(settings.welcome.title || 'Welcome!')
            .setDescription(contentText)
            .setColor(settings.welcome.color || '#5865F2');

          if (settings.welcome.showUserAvatar) {
            embed.setThumbnail(member.user.displayAvatarURL());
          }
          if (settings.welcome.showServerIcon && member.guild.iconURL()) {
            embed.setAuthor({ name: member.guild.name, iconURL: member.guild.iconURL() });
          }
          if (settings.welcome.bottomImage) {
            embed.setImage(settings.welcome.bottomImage);
          }
          
          const footerStr = (settings.welcome.footerText || 'Member Count: {server.memberCount}')
            .replace(/{server.memberCount}/g, member.guild.memberCount.toString());
          
          embed.setFooter({ text: footerStr });

          welcomeChannel.send({ embeds: [embed] }).catch(err => console.error('Failed to send welcome embed', err));
        } else {
          welcomeChannel.send({ content: contentText }).catch(err => console.error('Failed to send welcome text', err));
        }
      }
    }

    // AntiRaid Account Age Protection
    if (settings?.antiraid?.enabled) {
      const ageInDays = (Date.now() - member.user.createdTimestamp) / (1000 * 60 * 60 * 24);
      if (ageInDays < settings.antiraid.accountAgeMinDays) {
        addGuildAudit(guildId, 'antiraid', 'JOIN_QUARANTINE', `Quarantined member ${member.user.tag} (Account age: ${Math.round(ageInDays * 10) / 10} days, threshold: ${settings.antiraid.accountAgeMinDays} days)`);

        try {
          if (settings.antiraid.action === 'timeout') {
            await member.timeout(1000 * 60 * 60 * 24, 'NexusBot AntiRaid Quarantine: Account is too new.');
            await member.send(`🔒 You have been placed in temporary quarantine in **${member.guild.name}** because your Discord account is less than ${settings.antiraid.accountAgeMinDays} days old.`);
          } else if (settings.antiraid.action === 'kick') {
            await member.send(`🔒 You were kicked from **${member.guild.name}** because your Discord account is too new (<${settings.antiraid.accountAgeMinDays} days).`);
            await member.kick('NexusBot AntiRaid Quarantine');
          }
        } catch (e) {
          console.error('Failed to quarantine user', e);
        }
      }
    }
  });

  // Channel Delete Listener (AntiNuke Shield)
  client.on('channelDelete', async (channel) => {
    if (!channel.guildId) return;
    const guildId = channel.guildId;
    const settings = getGuildSettings(guildId);
    if (!settings?.antinuke?.enabled) return;

    // Track rapid deletions
    const now = Date.now();
    let deletions = deletionTrackers.get(guildId) || [];
    deletions.push(now);
    deletions = deletions.filter(t => now - t < 60000); // 1 minute sliding window
    deletionTrackers.set(guildId, deletions);

    if (deletions.length > settings.antinuke.channelDeleteThreshold) {
      addGuildAudit(guildId, 'antinuke', 'SHIELD_TRIGGER', `Shield triggered: Exceeded channel delete threshold (${settings.antinuke.channelDeleteThreshold} deletes / min)`);
      
      // Perform automated action, like locking down permissions or alert
      console.log(`[AntiNuke Shield Triggered] Bulk deletion in ${guildId}`);
    }
  });

  client.login(token).catch(err => {
    console.error('[NexusBot Gateway] Failed to log in with token.', err);
  });

  return client;
}
